package com.acme.relay.config;

import java.io.IOException;
import java.io.Reader;
import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Properties;
import java.util.Set;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the relay's configuration from a properties file.
 *
 * <p>Anything wrong with the file is reported, all problems at once, as a {@link ConfigException}:
 * an invalid value is never replaced by a default. Defaults only apply to keys that are absent.
 */
public final class ConfigLoader {
    static final int DEFAULT_WORKER_THREADS = 4;
    static final int DEFAULT_QUEUE_CAPACITY = 1000;
    static final int DEFAULT_RETRY_ATTEMPTS = 3;
    static final Duration DEFAULT_REQUEST_TIMEOUT = Duration.ofSeconds(30);

    private static final String UPSTREAM_URL = "upstream.url";
    private static final String API_TOKEN = "api.token";
    private static final String WORKER_THREADS = "worker.threads";
    private static final String QUEUE_CAPACITY = "queue.capacity";
    private static final String RETRY_MAX_ATTEMPTS = "retry.max-attempts";
    private static final String REQUEST_TIMEOUT = "request.timeout";
    private static final String METRICS_ENABLED = "metrics.enabled";

    private static final Set<String> KNOWN_KEYS = Set.of(
            UPSTREAM_URL, API_TOKEN, WORKER_THREADS, QUEUE_CAPACITY,
            RETRY_MAX_ATTEMPTS, REQUEST_TIMEOUT, METRICS_ENABLED);

    private static final Pattern DURATION = Pattern.compile("(\\d+)(ms|s|m)");

    private final Properties properties;
    private final List<String> problems = new ArrayList<>();

    private ConfigLoader(Properties properties) {
        this.properties = properties;
    }

    public static ServiceConfig load(Path file) {
        ConfigLoader loader = new ConfigLoader(read(file));
        ServiceConfig config = loader.parse();
        if (!loader.problems.isEmpty()) {
            throw new ConfigException(file, loader.problems);
        }
        return config;
    }

    private static Properties read(Path file) {
        Properties properties = new Properties();
        try (Reader reader = Files.newBufferedReader(file)) {
            properties.load(reader);
        } catch (IOException | IllegalArgumentException e) {
            throw new ConfigException(file, List.of("cannot read the file (" + e + ")"));
        }
        return properties;
    }

    private ServiceConfig parse() {
        rejectUnknownKeys();
        return new ServiceConfig(
                uri(UPSTREAM_URL),
                requiredText(API_TOKEN),
                intValue(WORKER_THREADS, DEFAULT_WORKER_THREADS, 1),
                intValue(QUEUE_CAPACITY, DEFAULT_QUEUE_CAPACITY, 1),
                intValue(RETRY_MAX_ATTEMPTS, DEFAULT_RETRY_ATTEMPTS, 0),
                duration(REQUEST_TIMEOUT, DEFAULT_REQUEST_TIMEOUT),
                bool(METRICS_ENABLED, false));
    }

    private void rejectUnknownKeys() {
        Set<String> unknown = new TreeSet<>(properties.stringPropertyNames());
        unknown.removeAll(KNOWN_KEYS);
        for (String key : unknown) {
            problems.add(key + " is not a known setting (known settings: " + new TreeSet<>(KNOWN_KEYS) + ")");
        }
    }

    private String requiredText(String key) {
        String value = properties.getProperty(key);
        if (value == null || value.isBlank()) {
            problems.add(key + " is required");
            return null;
        }
        return value.trim();
    }

    private URI uri(String key) {
        String raw = requiredText(key);
        if (raw == null) {
            return null;
        }
        try {
            URI uri = new URI(raw);
            if (!uri.isAbsolute() || uri.getHost() == null) {
                problems.add(key + " must be an absolute URL with a host, got '" + raw + "'");
                return null;
            }
            return uri;
        } catch (java.net.URISyntaxException e) {
            problems.add(key + " is not a valid URL, got '" + raw + "'");
            return null;
        }
    }

    private int intValue(String key, int defaultValue, int minimum) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        try {
            int value = Integer.parseInt(raw.trim());
            if (value < minimum) {
                problems.add(key + " must be at least " + minimum + ", got '" + raw.trim() + "'");
                return defaultValue;
            }
            return value;
        } catch (NumberFormatException e) {
            problems.add(key + " must be a whole number, got '" + raw.trim() + "'");
            return defaultValue;
        }
    }

    private Duration duration(String key, Duration defaultValue) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        Matcher matcher = DURATION.matcher(raw.trim());
        if (!matcher.matches()) {
            problems.add(key + " must be a number followed by ms, s or m (e.g. 30s), got '" + raw.trim() + "'");
            return defaultValue;
        }
        try {
            long amount = Long.parseLong(matcher.group(1));
            Duration duration = switch (matcher.group(2)) {
                case "ms" -> Duration.ofMillis(amount);
                case "s" -> Duration.ofSeconds(amount);
                default -> Duration.ofMinutes(amount);
            };
            if (duration.isZero()) {
                problems.add(key + " must be greater than zero, got '" + raw.trim() + "'");
            }
            return duration;
        } catch (ArithmeticException | NumberFormatException e) {
            problems.add(key + " is too large, got '" + raw.trim() + "'");
            return defaultValue;
        }
    }

    private boolean bool(String key, boolean defaultValue) {
        String raw = properties.getProperty(key);
        if (raw == null) {
            return defaultValue;
        }
        String value = raw.trim();
        if (value.equalsIgnoreCase("true") || value.equalsIgnoreCase("false")) {
            return Boolean.parseBoolean(value);
        }
        problems.add(key + " must be true or false, got '" + value + "'");
        return defaultValue;
    }
}

